local shape_chunks = {}
for i = 1, 9 do
  shape_chunks[i] = MODULE .. string.format(".shapes_%03d", i)
end

local where -- shape name -> file number, built on the first lookup

-- The registry: a lookup of a shape not loaded yet loads its whole file. An unknown name is nil. A
-- missing file raises, as a missing module does.
local shapes = setmetatable({}, {
  __index = function(registry, name)
    if where == nil then
      where = {}
      for file, shape in string.gmatch(SHAPES, "(%d+) ([^\n]+)") do
        where[shape] = file
      end
      SHAPES = nil
    end
    local file = where[name]
    if file == nil then
      return nil
    end
    for k, node in pairs(require(MODULE .. ".shapes_" .. file)) do
      rawset(registry, k, node)
    end
    return rawget(registry, name)
  end,
})

local classes = {}

classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
  fields = { "details" },
})
classes.CachedContentTooFewTokens = errors.define({
  tag = "CachedContentTooFewTokens",
  categories = { "BadRequestError" },
  matchers = {
    { status = 400, message = { includes = "The minimum token count to start explicit caching" } },
  },
  fields = { "details" },
})
classes.Conflict = errors.define({
  tag = "Conflict",
  categories = { "ConflictError" },
  matchers = { { status = 409 } },
  fields = { "details" },
})
classes.DataLabelingJobDeprecated = errors.define({
  tag = "DataLabelingJobDeprecated",
  categories = { "BadRequestError" },
  matchers = { { status = 400, message = { includes = "DataLabelingJob is deprecated" } } },
  fields = { "details" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
  fields = { "details" },
})
classes.GovernedAgentNotFound = errors.define({
  tag = "GovernedAgentNotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 400, message = { matches = "^Agent \\S+/agents/\\S+ not found" } } },
  fields = { "details" },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
  fields = { "details" },
})
classes.ReasoningEngineNotRunning = errors.define({
  tag = "ReasoningEngineNotRunning",
  categories = { "BadRequestError" },
  matchers = { { status = 400, message = { includes = "does not have running instances" } } },
  fields = { "details" },
})
classes.SandboxEnvironmentsNotEnabled = errors.define({
  tag = "SandboxEnvironmentsNotEnabled",
  categories = { "ServerError" },
  matchers = { { status = 501 } },
  fields = { "details" },
})

local ops = {}
for i = 1, 5 do
  for name, op in pairs(require(MODULE .. string.format(".ops_%03d", i))) do
    ops[name] = op
  end
end

return {
  name = "gcp.aiplatform_v1",
  shapes = shapes,
  errors = classes,
  ops = ops,
  shape_chunks = shape_chunks,
  telemetry = {
    system = "gcp-api",
    prefix = "Aiplatform",
    service = "aiplatform",
    labels = "gcp",
    attributes = { ["gcp.client.service"] = "aiplatform" },
    propagate = "w3c",
    response_headers = {
      { header = "x-request-id", name = "http.response.header.x-request-id", transform = "list" },
      { header = "request-id", name = "http.response.header.request-id", transform = "list" },
      {
        header = "x-goog-request-id",
        name = "http.response.header.x-goog-request-id",
        transform = "list",
      },
    },
  },
}
